def get_precision(hypothesis, reference, n):

    h_tokens = tokenize(hypothesis)
    r_tokens = tokenize(reference)

    num_hyp_tokens = len(h_tokens)
    num_ref_tokens = len(r_tokens)
    num_matches_n = 0
    num_matches_n_ref = 0

    for i in range(min(num_hyp_tokens, num_ref_tokens)):
        if h_tokens[i] == r_tokens[i]:
            num_matches_n += 1
            num_matches_n_ref += 1

    return num_matches_n / (num_hyp_tokens ** (1 / n)), num_matches_n_ref

