import os
import functools
from typing import Callable
from pathlib import Path

def _get_file_size(path: Path) -> int:
    try:
        return path.stat().st_size
    except FileNotFoundError:
        return 0

return functools.reduce(lambda x, y: x + y, (map(Path(path).rglob('**'), _get_file_size))


try:
    for dirpath, dirnames, filenames in os.walk(path):
        for f in filenames:
            if f.endswith('.py') or f.endswith('.txt'):
                fp = os.path.join(dirpath, f)
                size = os.path.getsize(fp)
                yield fp, size
except FileNotFoundError:
    pass

try:
    return sum(
        _get_file_size(os.path.join(path, file))
        for file in os.listdir(path)
        if os.path.isfile(file)
        )
except FileNotFoundError:
    return 0

# Set the total size to 0
total_size = 0

# Iterate over the files and folders in the specified path
for f in os.scandir(path):

    # If the file is a regular file, add its size to the total size
    if f.is_file():
        try:
            total_size += f.stat().st_size
        except FileNotFoundError:
            # Ignore errors
            pass
    # If the file is a directory, recursively calculate the total size of its contents
    elif f.is_dir():
        total_size += _get_folder_size(f.path)

# Return the total size
return total_size

