from pydantic import BaseModel, Field

class Validator(BaseModel):

    @staticmethod
    def __init__(cls, **kwargs):
        cls.__dict__['field1'] = kwargs.get(field1)
        cls.__dict__['field2'] = kwargs.get(field2)

        cls.validate(cls)

    @classmethod
    def validate(cls, model: 'Validator') -> 'Validator':
        if len(model.field1) != len(model.field2):
            raise ValueError(
                f"The number of arrays in field1 ({len(model.field1)}) does not match the number of arrays in field2 ({len(model.field2)})."
            )

        for i in range(len(model.field1)):
            if model.field1[i].shape != model.field2[i].shape:
                raise ValueError(
                    f"The shape of the arrays in field1 ({model.field1[i].shape}) does not match the shape of the corresponding array in field2 ({model.field2[i].shape}).")

        return model

return Field(
    None,
    validators=[
        Validator
    ]
)

