def _pack_greedily(num_workers, user_items, weights=None, file_size=False):
    num_nodes = _get_num_nodes()
    node_rank = _get_node_rank()

    # Get the total number of workers.
    world_size = num_nodes * num_workers

    # Create a list of lists, where each sublist will contain the items assigned to a worker.
    worker_items = [[] for _ in range(world_size)]

    # Calculate the total weight of all items.
    total_weight = 0
    if weights is None:
        weights = [1] * len(user_items)
    for weight in weights:
        total_weight += weight

    # Assign items to workers based on weights.
    for i, item in enumerate(user_items):
        # Get the worker to which the item should be assigned.
        worker_id = _get_worker_for_item(i, weights, world_size)

        # Add the item to the worker's list.
        worker_items[worker_id].append(item)

    # Print the distribution details.
    if file_size:
        print("Distribution of items among workers (file size):")
    else:
        print("Distribution of items among workers (weight):")
    for i in range(world_size):
        if i == node_rank * num_workers:
            print("  Node {}:".format(node_rank))
        if len(worker_items[i]) > 0:
            if file_size:
                print("    Worker {}: {}".format(i, _get_size_in_mb(worker_items[i])))
            else:
                print("    Worker {}: {}".format(i, _get_weight(worker_items[i])))
        if i == node_rank * num_workers + num_workers - 1:
            print("")

    # Shuffle the items for each worker.
    for worker_id in range(world_size):
        worker_items[worker_id] = _shuffle(worker_items[worker_id])

    return worker_items, weights

