class FpCounter(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        ctx.save_for_backward(input)
        return input

    @staticmethod
    def backward(ctx, grad_output):
        input = ctx.saved_tensors[0]
        flops = 1.0 * input.numel()
        return grad_output,

